package apps

import (
	"encoding/json"
	"testing"

	appv1alpha1 "github.com/bex-co/bex/lego/types/v1alpha1"
)

// Diagnostic only: constructed source state, actual unchanged applier. It
// records false field attribution; it is not a fixed-behavior regression.
func TestQaA903SourceFieldAttribution(t *testing.T) {
	live := appv1alpha1.AppSpec{Type: "web", Tier: "free", Runtime: "image", Image: "example.test/image:known", HealthCheckPath: "/"}
	want := live
	want.Image = ""
	want.Repo = "https://github.com/expressjs/serve-static"
	want.Branch = "master"
	want.Runtime = "node"
	want.BuildCommand = "build-known-fixture"
	want.StartCommand = "start-known-fixture"
	fields := map[string]BlueprintField{}
	for _, name := range []string{"name", "plan", "type", "autoDeploy", "healthCheckPath", "rootDir", "envVars", "repo", "branch", "runtime", "buildCommand", "startCommand"} {
		fields[name] = BlueprintField{}
	}
	type observation struct {
		Field string `json:"field"`
		Changed bool `json:"changed"`
		RepoBefore string `json:"repoBefore"`
		RepoAfter string `json:"repoAfter"`
		ImageBefore string `json:"imageBefore"`
		ImageAfter string `json:"imageAfter"`
	}
	var rows []observation
	for name := range fields {
		probe := *live.DeepCopy()
		changed, err := ApplyBlueprintServiceSpec(&probe, want, oneField(fields, name))
		if err != nil { t.Fatal(err) }
		rows = append(rows, observation{name, changed, live.Repo, probe.Repo, live.Image, probe.Image})
		if name == "name" && (!changed || probe.Repo != want.Repo || probe.Image != "") {
			t.Fatal("diagnostic premise no longer holds: name-only probe must currently switch the source")
		}
	}
	b, err := json.Marshal(rows)
	if err != nil { t.Fatal(err) }
	t.Log("QA_A903_FIELD_PROBES " + string(b))
	// Control: keeping the source stable must not mark the matching name.
	stable := live
	if changed, err := ApplyBlueprintServiceSpec(&stable, live, oneField(fields, "name")); err != nil || changed {
		t.Fatalf("same-image name control changed=%v err=%v", changed, err)
	}
}

