// blueprintPlanFieldChanges reports which of a manifest's declared fields
// actually differ from the live resource — not, as it did until w4/m124, every
// field the manifest happens to declare.
//
// The old behavior made the plan unreadable in the way that matters: two
// key-value manifests differing in `maxmemoryPolicy` produced byte-identical
// output, and a service manifest reported all ten of its declared paths
// whatever the difference was. A field list that does not depend on the diff is
// not a diff.
//
// It is computed by applying each declared field ALONE to a copy of the live
// spec and asking whether the spec moved, so the answer comes from the very
// appliers a real sync would run. A diff derived any other way can disagree
// with what apply does, which is the failure this whole milestone is about.
//
// applyOne returns whether applying just `name` changed the resource.
func blueprintPlanFieldChanges(fields map[string]BlueprintField, applyOne func(name string) (bool, error)) []BlueprintFieldChange {
	changes := make([]BlueprintFieldChange, 0, len(fields))
	for name := range fields {
		changed, err := applyOne(name)
		if err != nil {
			// A field that cannot be applied in isolation is reported rather
			// than dropped: the plan must not claim a resource is unaffected by
			// something it could not evaluate.
			changes = append(changes, BlueprintFieldChange{Path: name})
			continue
		}
		if changed {
			changes = append(changes, BlueprintFieldChange{Path: name})
		}
	}
	sort.Slice(changes, func(i, j int) bool { return changes[i].Path < changes[j].Path })
	return changes
}

// blueprintDeclaredFieldChanges is the fallback for a resource kind with no
// per-field applier to probe (env groups, whose values are write-only): report
// the declared set, sorted, as before.
func blueprintDeclaredFieldChanges(fields map[string]BlueprintField) []BlueprintFieldChange {
	changes := make([]BlueprintFieldChange, 0, len(fields))
	for name := range fields {
		changes = append(changes, BlueprintFieldChange{Path: name})
	}
	sort.Slice(changes, func(i, j int) bool { return changes[i].Path < changes[j].Path })
	return changes
}

// oneField narrows a declared field set to a single entry, so an applier can be
// run in isolation.
func oneField(fields map[string]BlueprintField, name string) map[string]BlueprintField {
	if f, ok := fields[name]; ok {

// applyBlueprintRepo applies a declared (or Blueprint-inherited) repo. A new
// repo is a source switch, as the source setter treats one
// (applySourceChange): its build replaces a former prebuilt image or rollback
// override, and the old origin's clone token and an image-only credential go
// with it (w8/m70). A branch names a ref of one repository, so the switch
// builds the entry's branch, as a create would: the declared one, the
// Blueprint's for its own repo, or the new repo's default (w8/m80) — never an
// image's placeholder or the old repo's. As the repo field's applier it runs
// before the branch and registryCredential appliers, so their declared values
// still win. The same repo, however spelled, keeps a rollback's image override
// and its branch.
func applyBlueprintRepo(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) {
	if blueprintRepoSwitch(*dst, want) {
		if prebuiltImageSource(*dst) {
			dst.RegistryCredentialID = nil
		}
		dst.Image = ""
		dst.CloneSecret = ""
		if want.Branch != "" {
			dst.Branch = want.Branch
		}
	}
	dst.Repo = want.Repo
}

// blueprintRepoSwitch reports whether next builds another repository than
// current, an image-backed service's none included.
func blueprintRepoSwitch(current, next appv1alpha1.AppSpec) bool {
	return next.Repo != "" && core.CanonicalRepo(next.Repo) != core.CanonicalRepo(current.Repo)

func ApplyBlueprintServiceSpec(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec, fields map[string]BlueprintField) (bool, error) {
	before := *dst.DeepCopy()
	// Refuse a shrink before anything is written, the same way the database
	// twin below refuses one. A disk cannot be shrunk at any layer — CRD, API,
	// or store — so a Blueprint that asks for it has to fail with a source
	// location rather than be silently clamped to the current size.
	if _, ok := fields["disk"]; ok && want.Disk != nil && dst.Disk != nil && want.Disk.SizeGB < dst.Disk.SizeGB {
		return false, &BlueprintFieldConflictError{
			Path:    "disk.sizeGB",
			Message: fmt.Sprintf("cannot shrink an existing disk (currently %dGB)", dst.Disk.SizeGB),
		}
	}
	present := func(name string) bool {
		_, ok := fields[name]
		return ok
	}

	for _, field := range blueprintServiceFieldAppliers {
		if anyPresent(fields, field.names...) {
			field.apply(dst, want)
		}
	}
	// A Git entry may take its repo from the Blueprint rather than declare
	// one; on an image-backed service that is a source switch too (w8/m70).
	if !present("repo") && !present("image") && want.Repo != "" && prebuiltImageSource(*dst) {
		applyBlueprintRepo(dst, want)
	}
	// A native or buildpack start command was baked into the image it built;
	// left on a prebuilt image it would run as that image's /bin/sh command
	// override, so a switch that declares no command drops it (w8/m70).
	if prebuiltImageSource(*dst) && !prebuiltImageSource(before) && !present("startCommand") && !present("dockerCommand") &&
		!readsDockerCommand(buildStrategy(before)) {
		dst.StartCommand = ""
	}

	// runtime and x-bex.builder are one build strategy with several
	// spellings, and an export writes a service's effective one (w4/193): a
	// Dockerfile build with no spec.runtime as runtime docker, a prebuilt
	// image as runtime image. Judged after every other field, against the
	// source and build inputs the sync leaves, declaring the strategy the
	// service builds with keeps its spelling, so bex's own export re-plans as
	// noop (w5/m117). An omitted builder is preserved, as before.
	if present("runtime") || present("builder") {
		next := *dst
		if present("runtime") {
			next.Runtime = want.Runtime
		}
		if present("builder") {
			next.Builder = want.Builder
		}
		// A source-kind switch takes the declared strategy even where the
		// left-behind spelling resolves to the same build (a stale runtime
		// image on a new repo reads as a Dockerfile build, w8/m70). The
		// declared kind decides, so a runtime-only plan probe agrees.
		if prebuiltImageSource(want) != prebuiltImageSource(before) || buildStrategy(next) != buildStrategy(*dst) {
			dst.Runtime, dst.Builder = next.Runtime, next.Builder
			// The Dockerfile-build settings an omission would keep do nothing
			// on another build, which create and update refuse (w5/090). One
			// the file declares there is refused before any apply.
			if buildStrategy(*dst) != buildDockerfile {
				if !present("dockerfilePath") {
					dst.DockerfilePath = ""
				}
				if !present("dockerContext") {
					dst.DockerContext = ""
				}
			}
		}
	}

	if present("buildFilter") {
		if want.BuildFilter == nil {
			dst.BuildFilter = nil
		} else {
			dst.BuildFilter = want.BuildFilter.DeepCopy()

}{
	{names: []string{"type"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) { dst.Type = want.Type }},
	{names: []string{"schedule"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) { dst.Schedule = want.Schedule }},
	{names: []string{"repo"}, apply: applyBlueprintRepo},
	{names: []string{"image"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) {
		// A declared image is the whole source, as the source setter treats
		// one (resolveSourcePatch): a former repo would otherwise build again
		// on the next push (w8/m70). Branch, rootDir and commands stay for a
		// switch back. (A real entry cannot declare both; the guard keeps the
		// all-fields parity probe meaningful.)
		if want.Image != "" && want.Repo == "" {
			dst.Repo = ""
		}
		dst.Image = want.Image
		// image.creds rides the image field's presence: a resolved credential
		// rebinding applies with it, while a creds-less image change leaves an
		// existing binding untouched (preserve-on-omission, like the field).
		if want.RegistryCredentialID != nil {
			dst.RegistryCredentialID = clonePtr(want.RegistryCredentialID)
		}
	}},
	{names: []string{"branch"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) { dst.Branch = want.Branch }},
	{names: []string{"rootDir"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) { dst.RootDir = want.RootDir }},
	{names: []string{"buildCommand"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) { dst.BuildCommand = want.BuildCommand }},
	// A cron job's command lives in Spec.Command, not Spec.StartCommand —
	// SetCommands has always known that, and so does the exporter, which writes
	// Spec.Command out as `startCommand` (or `dockerCommand` for a docker or
	// image runtime). These two appliers did not: they wrote every declared command
	// into StartCommand, so an exported cron gained a StartCommand it never had
	// while keeping its Command, and re-planned as `update` forever. Found by
	// w4/m124's round-trip guard, not by the QA pass that opened the milestone
	// — the same exporter/planner disagreement as `domains`, one field over.
	{names: []string{"startCommand"}, apply: applyBlueprintCommand},
	{names: []string{"dockerCommand"}, apply: applyBlueprintCommand},
	{names: []string{"dockerfilePath"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) { dst.DockerfilePath = want.DockerfilePath }},
	{names: []string{"dockerContext"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) { dst.DockerContext = want.DockerContext }},
	{names: []string{"registryCredential"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) {
		dst.RegistryCredentialID = clonePtr(want.RegistryCredentialID)
	}},
	{names: []string{"plan"}, apply: func(dst *appv1alpha1.AppSpec, want appv1alpha1.AppSpec) { dst.Tier = want.Tier }},

	}
}

// TestPlanNamesOnlyTheFieldThatChanged is the other half: the loop being closed
// must not come from a planner that stopped noticing things. Until w4/m124
// changedFields listed every field the MANIFEST DECLARED, so two key-value
// manifests differing in maxmemoryPolicy produced byte-identical plans — a
// field list that does not depend on the diff is not a diff.
func TestPlanNamesOnlyTheFieldThatChanged(t *testing.T) {
	allowHighAvailabilityOnEveryPlan(t)
	svc, req := roundTripFixture()
	ctx := context.Background()
	out, err := svc.GenerateBlueprint(ctx, req)
	if err != nil {
		t.Fatalf("GenerateBlueprint: %v", err)
	}

	for _, tc := range []struct {
		name      string
		from, to  string
		wantKind  string
		wantField string
	}{
		{"key value eviction policy", "maxmemoryPolicy: allkeys-lru", "maxmemoryPolicy: noeviction", "keyvalue", "maxmemoryPolicy"},
		{"postgres plan", "plan: basic-1gb", "plan: basic-256mb", "postgres", "plan"},
		{"service health check", "healthCheckPath: /healthz", "healthCheckPath: /live", "service", "healthCheckPath"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if !strings.Contains(out.Manifest, tc.from) {
				t.Skipf("export does not contain %q; nothing to perturb", tc.from)
			}
			changed := strings.Replace(out.Manifest, tc.from, tc.to, 1)
			v, err := svc.ValidateBlueprint(ctx, "", changed, "")
			if err != nil || v.Plan == nil {
				t.Fatalf("ValidateBlueprint: %+v err=%v", v, err)
			}
			plan := *v.Plan
			var updates int
			for _, action := range plan.Actions {
				if action.Operation == BlueprintPlanNoop {
					continue
				}
				updates++
				paths := fieldPaths(action.ChangedFields)
				// Exactly the perturbed field — not the declared set, and
				// never the match key, which cannot have changed.
				if len(paths) != 1 || paths[0] != tc.wantField {
					t.Errorf("%s %q changedFields = %v, want exactly [%s]", action.Kind, action.Name, paths, tc.wantField)
				}
			}
			if updates == 0 {
				t.Error("a real change was not detected at all — the planner has gone blind")
			}
		})
	}
}

